using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver.
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval — returns JsonTypeInfo<Person> directly.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

// Round-trip to prove it works:
var json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Person? p = JsonSerializer.Deserialize(json, personInfo);
Console.WriteLine($"Round-trip: {p}");

// 2) Probe without throwing — TryGetTypeInfo returns false if unavailable.
//    With the default resolver everything is available, so first show success:
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? probed))
    Console.WriteLine($"TryGetTypeInfo(Person) succeeded: {probed!.Type.Name}");

// Now use options with NO resolver so the type is genuinely unavailable:
var empty = new JsonSerializerOptions { TypeInfoResolver = null };
if (!empty.TryGetTypeInfo(typeof(Person), out _))
    Console.WriteLine("TryGetTypeInfo(Person) correctly returned false (no resolver).");

record Person(string Name, int Age);

